CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE institutions (
 id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, calendar TEXT NOT NULL DEFAULT 'unknown'
 CHECK(calendar IN ('semester','quarter','other','unknown')), website TEXT,
 coverage_status TEXT NOT NULL DEFAULT 'pending' CHECK(coverage_status IN ('pending','inspected','confirmed','no_qualifying_program_found','inaccessible')),
 coverage_note TEXT NOT NULL DEFAULT '', last_inspected TEXT
);
CREATE TABLE institution_aliases(institution_id TEXT NOT NULL REFERENCES institutions(id) ON DELETE CASCADE, alias TEXT NOT NULL, PRIMARY KEY(institution_id,alias));
CREATE TABLE hosting_units(id INTEGER PRIMARY KEY, institution_id TEXT NOT NULL REFERENCES institutions(id), name TEXT NOT NULL, UNIQUE(institution_id,name));
CREATE TABLE rankings(id INTEGER PRIMARY KEY,institution_id TEXT NOT NULL REFERENCES institutions(id),publisher TEXT NOT NULL,edition TEXT NOT NULL,category TEXT NOT NULL,rank INTEGER NOT NULL CHECK(rank>0),source_url TEXT NOT NULL,verification_status TEXT NOT NULL DEFAULT 'secondary_reported',UNIQUE(institution_id,publisher,edition,category));
CREATE TABLE metadata(key TEXT PRIMARY KEY,value_json TEXT NOT NULL CHECK(json_valid(value_json)));
CREATE TABLE scrape_runs(id INTEGER PRIMARY KEY,adapter TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL CHECK(status IN ('running','success','partial','failed')),error TEXT);
CREATE TABLE coverage_events(id INTEGER PRIMARY KEY,institution_id TEXT NOT NULL REFERENCES institutions(id),status TEXT NOT NULL CHECK(status IN ('pending','inspected','confirmed','no_qualifying_program_found','inaccessible')),checked_at TEXT NOT NULL,note TEXT NOT NULL,sources_json TEXT NOT NULL CHECK(json_valid(sources_json)),fingerprint TEXT NOT NULL UNIQUE);
CREATE TABLE discoveries(id INTEGER PRIMARY KEY,institution_id TEXT NOT NULL REFERENCES institutions(id),title TEXT NOT NULL,kind TEXT,award_level TEXT,url TEXT NOT NULL,UNIQUE(institution_id,title,url));
CREATE TABLE programs(id TEXT PRIMARY KEY,institution_id TEXT NOT NULL REFERENCES institutions(id),hosting_unit_id INTEGER REFERENCES hosting_units(id),title TEXT NOT NULL,award_level TEXT NOT NULL,program_kind TEXT NOT NULL CHECK(program_kind IN ('degree','minor','concentration','additional_major')),status TEXT NOT NULL CHECK(status IN ('active','announced','discontinued','unknown')),first_offered_json TEXT CHECK(first_offered_json IS NULL OR json_valid(first_offered_json)),overview TEXT NOT NULL DEFAULT '',catalog_year TEXT,verification_status TEXT NOT NULL CHECK(verification_status IN ('confirmed','partial')),curriculum_status TEXT NOT NULL CHECK(curriculum_status IN ('complete','partial','pending')),last_verified TEXT NOT NULL,content_hash TEXT NOT NULL,record_json TEXT NOT NULL CHECK(json_valid(record_json)));
CREATE TABLE sources(program_id TEXT NOT NULL REFERENCES programs(id) ON DELETE CASCADE,id TEXT NOT NULL,url TEXT NOT NULL,title TEXT NOT NULL,fetched_at TEXT,source_date TEXT,catalog_year TEXT,locator TEXT,confidence TEXT CHECK(confidence IN ('high','medium','low')),PRIMARY KEY(program_id,id));
CREATE TABLE program_links(program_id TEXT NOT NULL REFERENCES programs(id) ON DELETE CASCADE,kind TEXT NOT NULL,url TEXT NOT NULL,label TEXT,PRIMARY KEY(program_id,kind,url));
CREATE TABLE courses(program_id TEXT NOT NULL REFERENCES programs(id) ON DELETE CASCADE,id TEXT NOT NULL,code TEXT NOT NULL,name TEXT,description TEXT,prerequisites TEXT,credits REAL CHECK(credits IS NULL OR credits>=0),credit_unit TEXT NOT NULL,category TEXT NOT NULL,source_id TEXT,url TEXT,public_site TEXT,syllabus TEXT,PRIMARY KEY(program_id,id),FOREIGN KEY(program_id,source_id) REFERENCES sources(program_id,id));
CREATE TABLE requirement_groups(program_id TEXT NOT NULL REFERENCES programs(id) ON DELETE CASCADE,id TEXT NOT NULL,parent_id TEXT,title TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('all','choose_courses','choose_credits','alternative','note')),choose_count INTEGER CHECK(choose_count IS NULL OR choose_count>0),credits REAL CHECK(credits IS NULL OR credits>0),credit_unit TEXT NOT NULL,category TEXT NOT NULL,source_id TEXT,source_text TEXT,summary TEXT,PRIMARY KEY(program_id,id),FOREIGN KEY(program_id,parent_id) REFERENCES requirement_groups(program_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(program_id,source_id) REFERENCES sources(program_id,id),CHECK(parent_id IS NULL OR parent_id!=id));
CREATE TABLE requirement_courses(program_id TEXT NOT NULL,requirement_id TEXT NOT NULL,course_id TEXT NOT NULL,PRIMARY KEY(program_id,requirement_id,course_id),FOREIGN KEY(program_id,requirement_id) REFERENCES requirement_groups(program_id,id) ON DELETE CASCADE,FOREIGN KEY(program_id,course_id) REFERENCES courses(program_id,id) ON DELETE CASCADE);
CREATE TABLE outcomes(program_id TEXT NOT NULL REFERENCES programs(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,text TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('source_stated','inferred_taxonomy')),source_id TEXT,locator TEXT,PRIMARY KEY(program_id,ordinal),FOREIGN KEY(program_id,source_id) REFERENCES sources(program_id,id));
CREATE TABLE program_revisions(id INTEGER PRIMARY KEY,program_id TEXT NOT NULL REFERENCES programs(id),content_hash TEXT NOT NULL,record_json TEXT NOT NULL CHECK(json_valid(record_json)),changed_at TEXT NOT NULL,scrape_run_id INTEGER REFERENCES scrape_runs(id),UNIQUE(program_id,content_hash));
CREATE TABLE manual_overrides(program_id TEXT NOT NULL REFERENCES programs(id),field TEXT NOT NULL,value_json TEXT NOT NULL CHECK(json_valid(value_json)),reason TEXT NOT NULL,evidence_url TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(program_id,field));
CREATE TABLE source_snapshots(id INTEGER PRIMARY KEY,run_id INTEGER NOT NULL REFERENCES scrape_runs(id),program_id TEXT REFERENCES programs(id),url TEXT NOT NULL,fetched_at TEXT NOT NULL,content_hash TEXT NOT NULL,http_status INTEGER NOT NULL,cached INTEGER NOT NULL CHECK(cached IN (0,1)),changed INTEGER NOT NULL CHECK(changed IN (0,1)));
CREATE TABLE extraction_candidates(id INTEGER PRIMARY KEY,program_id TEXT NOT NULL REFERENCES programs(id),run_id INTEGER NOT NULL REFERENCES scrape_runs(id),source_url TEXT NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),content_hash TEXT NOT NULL,created_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')),UNIQUE(program_id,source_url,content_hash));
CREATE TABLE csrankings_config(id INTEGER PRIMARY KEY CHECK(id=1),fields_json TEXT NOT NULL CHECK(json_valid(fields_json)),year_start INTEGER NOT NULL,year_end INTEGER NOT NULL,geographic_filter TEXT NOT NULL,method TEXT NOT NULL,source_snapshot TEXT NOT NULL,source_url TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('not_imported','permission_required','available')),CHECK(year_end>=year_start));
CREATE TABLE csrankings_observations(institution_id TEXT NOT NULL REFERENCES institutions(id),field TEXT NOT NULL,value REAL,rank INTEGER,missingness TEXT NOT NULL,config_id INTEGER NOT NULL REFERENCES csrankings_config(id),PRIMARY KEY(institution_id,field,config_id),CHECK((value IS NULL AND rank IS NULL) OR missingness='observed'));
CREATE INDEX programs_institution ON programs(institution_id);
CREATE INDEX snapshots_url ON source_snapshots(url,id);
CREATE INDEX groups_parent ON requirement_groups(program_id,parent_id);
